export const brl=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(value);
export function checkoutFor(plan){
 if(!plan.approved||!plan.checkoutUrl)return null;
 try{const url=new URL(plan.checkoutUrl);return url.protocol==='https:'?url.href:null;}catch{return null;}
}
